    static class AAirplane {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int p = in.nextInt();
            int q = in.nextInt();
            int r = in.nextInt();
            out.println(Math.min(Math.min(p + q, p + r), q + r));
        }

