    		f2 = false;
    		for (int i = 0; i < N; i++) {
    			if(H[i] > 0) {
    				if(!f2) {
    					ans++;
    					f2 = true;
    				}
        			H[i]--;
        			f = false;
    			} else {
    				f2 = false;
    			}
    		}
    		if(f)	break;
		}
    	out.println(ans);
    }
